#!/usr/bin/env python3
"""Write an Apache .htaccess for the built site.

    build_htaccess.py <site dir>

The site's redirects and headers are kept in Netlify's formats
(public/_redirects and public/_headers), which an Apache-compatible host
ignores. This turns them into the equivalent .htaccess rules, so those two
files stay the only place the rules are written. It also sets the site's own
404 page and blocks the deploy list.

Set SITE_OFFLINE=true to take the site down: every address then answers
"503 Service Unavailable" and nothing else is served. The files stay on the
server, so unsetting it and redeploying brings the site straight back.

Supported _redirects lines:  /old/  /new/  301      and      /old/*  /new/  301
Supported _headers blocks:   /*   /folder/*   /exact/path
"""
from __future__ import annotations

import os
import re
import sys
from pathlib import Path


def quote(value: str) -> str:
    return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'


def source_pattern(source: str) -> str:
    """A Netlify path as a mod_rewrite pattern (no leading slash in .htaccess).
    Like Netlify, the trailing slash is optional."""
    wildcard = source.endswith("/*")
    path = source[:-2] if wildcard else source
    body = re.escape(path.strip("/")).replace("\\-", "-").replace("\\/", "/")
    if wildcard:
        return f"^{body}(/.*)?$"
    return f"^{body}/?$" if body else "^$"


def read_redirects(path: Path) -> list[tuple[str, str, str]]:
    rules = []
    for number, line in enumerate(path.read_text().splitlines(), 1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        status = parts[2] if len(parts) > 2 else "301"
        if len(parts) not in (2, 3) or not parts[0].startswith("/") or status not in ("301", "302") \
                or "*" in parts[0][:-1] or ":" in parts[0] or ":splat" in parts[1]:
            sys.exit(f"{path}:{number}: this kind of redirect is not supported by build_htaccess.py: {line}")
        rules.append((parts[0], parts[1], status))
    return rules


def read_headers(path: Path) -> list[tuple[str, list[tuple[str, str]]]]:
    blocks: list[tuple[str, list[tuple[str, str]]]] = []
    for number, line in enumerate(path.read_text().splitlines(), 1):
        if not line.strip() or line.strip().startswith("#"):
            continue
        if not line[0].isspace():
            target = line.strip()
            if not target.startswith("/") or "*" in target.rstrip("*") or ":" in target:
                sys.exit(f"{path}:{number}: this kind of path is not supported by build_htaccess.py: {target}")
            blocks.append((target, []))
        else:
            name, _, value = line.strip().partition(":")
            if not blocks or not value:
                sys.exit(f"{path}:{number}: could not read this header line: {line}")
            blocks[-1][1].append((name.strip(), value.strip()))
    return blocks


OFFLINE = """\
# Generated by .github/scripts/build_htaccess.py with SITE_OFFLINE=true.
# The site is switched off: every address answers 503.

ErrorDocument 503 "This site is temporarily unavailable."

<IfModule mod_headers.c>
  Header always set Cache-Control "no-store"
  Header always set X-Robots-Tag "noindex"
</IfModule>

<IfModule mod_rewrite.c>
  RewriteEngine On
  RewriteRule ^ - [R=503,L]
</IfModule>
<IfModule !mod_rewrite.c>
  <IfModule mod_authz_core.c>
    Require all denied
  </IfModule>
</IfModule>
"""


def build(site: Path) -> str:
    if os.environ.get("SITE_OFFLINE", "").lower() == "true":
        return OFFLINE
    redirects = read_redirects(site / "_redirects") if (site / "_redirects").exists() else []
    headers = read_headers(site / "_headers") if (site / "_headers").exists() else []

    out = [
        "# Generated by .github/scripts/build_htaccess.py from public/_redirects and",
        "# public/_headers. Do not edit here: change those files and redeploy.",
        "",
        "ErrorDocument 404 /404.html",
        "",
        "# The deploy list is for the deploy script only.",
        '<Files ".deploy-manifest">',
        "  <IfModule mod_authz_core.c>",
        "    Require all denied",
        "  </IfModule>",
        "  <IfModule !mod_authz_core.c>",
        "    Order allow,deny",
        "    Deny from all",
        "  </IfModule>",
        "</Files>",
        "",
    ]

    marks: list[str] = []          # rewrite rules that tag requests for path-specific headers
    header_lines: list[str] = []
    type_lines: list[str] = []
    for index, (target, pairs) in enumerate(headers):
        if target == "/*":
            condition = ""
        else:
            variable = f"HDR_{index}"
            marks.append(f"  RewriteRule {source_pattern(target)} - [E={variable}:1]")
            condition = f" env={variable}"
        for name, value in pairs:
            if name.lower() == "content-type":
                if target.endswith("*"):
                    sys.exit(f"_headers: Content-Type is only supported for a single file, not {target}")
                type_lines += [f"<Files {quote(target.rsplit('/', 1)[1])}>", f"  ForceType {quote(value)}", "</Files>"]
            else:
                header_lines.append(f"  Header always set {name} {quote(value)}{condition}")

    out += ["<IfModule mod_rewrite.c>", "  RewriteEngine On", ""]
    if marks:
        out += ["  # Tag requests that get path-specific headers (see mod_headers below).", *marks, ""]
    if redirects:
        out += [
            "  # Redirects from old addresses. As on Netlify, a real file or folder wins.",
            "  RewriteCond %{REQUEST_FILENAME} -f [OR]",
            "  RewriteCond %{REQUEST_FILENAME} -d",
            "  RewriteRule ^ - [L]",
            "",
        ]
        for source, target, status in redirects:
            out.append(f"  RewriteRule {source_pattern(source)} {target} [R={status},L,NE]")
    out += ["</IfModule>", ""]

    if header_lines:
        out += ["<IfModule mod_headers.c>", *header_lines, "</IfModule>", ""]
    if type_lines:
        out += [*type_lines, ""]
    return "\n".join(out)


def main() -> None:
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    site = Path(sys.argv[1])
    text = build(site)
    (site / ".htaccess").write_text(text)
    if text == OFFLINE:
        print("::warning::SITE_OFFLINE is true: this deploy switches the site off (503 for every address).")
    else:
        print(f"Wrote {site / '.htaccess'}: {text.count('[R=3')} redirects, {text.count('Header always set')} headers.")


if __name__ == "__main__":
    main()
